const gaps = $json; // response of Coverage Gaps
const u = gaps.uncovered || {};
const fullyUncovered = u.lines === 'all';
const nothingToCover = !fullyUncovered && (!u.lines || !u.lines.length);
const targetPath = gaps.covTestPath;
if (nothingToCover) return [{ json: { skip: true, reason: 'class fully covered', targetPath, projectTestPath: gaps.projectTestPath } }];
const constraints = (gaps.constraints || []).map(c => '- ' + c).join('\n');
const testClass = targetPath.split('/').pop().replace(/\.java$/, '');
const RULES = "\n- ONE test file only. Its public class name MUST equal the file name, and the package declaration MUST match the directory under src/test/java.\n- Use the SAME test framework and assertion library as the style reference (JUnit 5: org.junit.jupiter.api.Test/Assertions; JUnit 4: org.junit.Test/org.junit.Assert). Do NOT introduce a dependency the project does not already have.\n- Call only the PUBLIC API of the class under test. Never use reflection, setAccessible, or read source/bytecode.\n- Do NOT modify production code, existing tests, or the build files.\n- Deterministic: no network, no clock/randomness without fixing them, no reliance on file-system state or test execution order.\n- Every test must ASSERT a value or an observable side effect; a test that only checks \"does not throw\" is worthless.\n- The tests MUST compile and PASS against the CURRENT implementation.";
const system = 'You are an expert Java test engineer writing ' + (gaps.testFramework === 'junit4' ? 'JUnit 4' : gaps.testFramework === 'testng' ? 'TestNG' : 'JUnit 5') + ' tests to INCREASE LINE COVERAGE of one class. Reply ONLY with JSON: {"tests":[{"path":"...","content":"full test file content"}]}. Create a NEW test class only — never modify existing files. Required file path: ' + targetPath + ' (package ' + gaps.package + ', public class ' + testClass + '). Rules:' + RULES
  + (constraints ? '\nTeam constraints:\n' + constraints : '');
const prompt = 'CLASS UNDER TEST: ' + gaps.fqcn + '  (file ' + gaps.path + ', module ' + gaps.module + ', JDK ' + gaps.jdk + ')\n'
  + String(gaps.source || '').slice(0, 14000)
  + '\n\nUNCOVERED: ' + (fullyUncovered ? 'THE ENTIRE CLASS (no test executes it at all)' : 'source lines ' + JSON.stringify((u.lines || []).slice(0, 140)))
  + '\n\nEXISTING TEST (style reference — imports, assertion library, conventions; do NOT rewrite it):\n'
  + String(gaps.existingTest || '(none)').slice(0, 6000)
  + '\n\nWrite one test class that executes the uncovered lines and asserts real behaviour. JSON only.';
return [{ json: { system, prompt, json: true, maxTokens: 7000, temperature: 0.3, stage: 'improving_coverage', stageDetail: 'writing tests for uncovered code', targetPath, projectTestPath: gaps.projectTestPath } }];

const resp = $json;
const plan = $('Cov: Build Prompt').first().json;
let tests = (resp.ok && resp.json && Array.isArray(resp.json.tests)) ? resp.json.tests : [];
tests = tests
  .filter(t => t && typeof t.content === 'string' && t.content.trim().length > 20)
  .slice(0, 1)
  .map((t) => {
    let p = typeof t.path === 'string' ? t.path.replace(/^\.?\//, '') : '';
    // a Java file must live at the path its package + class name dictate, so trust our
    // computed target unless the model produced exactly that
    const safe = /(^|\/)src\/test\/java\/.+\.java$/.test(p) && !p.includes('..');
    if (!safe || p === plan.projectTestPath) p = plan.targetPath;
    // the public class name has to match the file name or javac refuses to compile
    const want = p.split('/').pop().replace(/\.java$/, '');
    let content = t.content;
    const declared = (content.match(/public\s+(?:final\s+|abstract\s+)?class\s+(\w+)/) || [])[1];
    if (declared && declared !== want) {
      content = content.replace(new RegExp('\\b' + declared + '\\b', 'g'), want);
    }
    return { path: p, content };
  });
return [{ json: { tests, paths: tests.map(t => t.path), count: tests.length } }];

